import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  shadcnDialogFooterClassName,
  shadcnDialogHeaderClassName,
} from "./view";

export {
  backdrop,
  cancelButton,
  close,
  closeButton,
  CloseDialog,
  Closed,
  CompletedCloseDialog,
  CompletedShowDialog,
  confirmButton,
  description,
  descriptionId,
  footer,
  GotAnimationMessage,
  init,
  Message,
  Model,
  open,
  Opened,
  OutMessage,
  panel,
  RequestedClose,
  RequestedOpen,
  root,
  ShowDialog,
  title,
  titleId,
  trigger,
  update,
  view,
} from "../../../foldkit/ui/dialog";
export type {
  ActionInputs,
  Commands,
  ContainerInputs,
  DialogAttribute,
  DialogChild,
  DialogVariant,
  InitConfig,
  InitReturn,
  PanelInputs,
  RenderInfo,
  RootInputs,
  TextInputs,
  TriggerInputs,
  UpdateReturn,
  ViewInputs,
} from "../../../foldkit/ui/dialog";

export {
  shadcnDialogBackdropClassName,
  shadcnDialogDescriptionClassName,
  shadcnDialogFooterClassName,
  shadcnDialogHeaderClassName,
  shadcnDialogPanelClassName,
  shadcnDialogTitleClassName,
} from "./view";

export type PartViewConfig = Readonly<{
  id?: string | undefined;
  children: readonly Html[];
  className?: string | undefined;
  style?: Readonly<Record<string, string>> | undefined;
}>;

const classNames = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const divPartView = <ParentMessage>(
  baseClassName: string,
  { id, children, className, style }: PartViewConfig
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(baseClassName, className)),
    ],
    children
  );
};

export const headerView = <ParentMessage>(config: PartViewConfig): Html =>
  divPartView<ParentMessage>(shadcnDialogHeaderClassName, config);

export const footerView = <ParentMessage>(config: PartViewConfig): Html =>
  divPartView<ParentMessage>(shadcnDialogFooterClassName, config);

export const shadcnDialogBackdropClassName =
  "fixed inset-0 bg-black/50 transition duration-150 ease-out data-[closed]:opacity-0";

export const shadcnDialogPanelClassName =
  "bg-white rounded-lg p-6 max-w-md mx-auto relative shadow-xl transition duration-150 ease-out data-[closed]:opacity-0 data-[closed]:scale-95";

export const shadcnDialogTitleClassName = "text-lg font-semibold text-gray-900";

export const shadcnDialogDescriptionClassName = "mt-2 text-base text-gray-600";

export const shadcnDialogHeaderClassName =
  "grid gap-2 text-center sm:text-left";

export const shadcnDialogFooterClassName =
  "flex flex-col-reverse gap-2 sm:flex-row sm:justify-end";

import { describe, expect, test } from "vitest";

import * as Dialog from "./index";

describe("shadcn Dialog registry view", () => {
  test("reuses the Foldkit Dialog functional contract", () => {
    expect(Dialog.init).toBeTypeOf("function");
    expect(Dialog.update).toBeTypeOf("function");
    expect(Dialog.root).toBeTypeOf("function");
    expect(Dialog.headerView).toBeTypeOf("function");
    expect(Dialog.footerView).toBeTypeOf("function");
    expect(Dialog.shadcnDialogPanelClassName).toContain("rounded");
  });
});
